// Host check of src/libs/video on synthetic clips (generated by run.py) and, as a smoke test,
// on any local media file.
//   video-check clip <file> <width> <height> <seconds> <audio:0|1>
//       plays on a simulated audio clock; checks size, first frame red, last frame blue, frame
//       count, audio length and level, pause and the end of playback.
//   video-check smoke <file> <seconds>
//       plays in real time for <seconds> (or to the end) and reports what was shown.
#include "storm/video/player.hpp"

#include <atomic>
#include <chrono>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <stdexcept>
#include <string>
#include <thread>

using namespace storm::video;

namespace
{
void require(bool condition, const std::string &message)
{
    if (!condition)
        throw std::runtime_error(message);
}

// Simulated output: plays at most what was written, when the test advances it.
class TestSink final : public AudioSink
{
  public:
    uint32_t write(const float *pcm, uint32_t frames) override
    {
        const uint64_t room = kCapacity - (written - played);
        const uint32_t accepted = static_cast<uint32_t>(std::min<uint64_t>(frames, room));
        for (uint32_t i = 0; i < accepted * kAudioChannels; ++i)
        {
            require(std::isfinite(pcm[i]), "finite PCM");
            energy = energy + double(pcm[i]) * pcm[i];
        }
        written += accepted;
        return accepted;
    }
    uint64_t playedFrames() override
    {
        return played;
    }
    void setPaused(bool value) override
    {
        paused = value;
    }
    void advance(uint64_t frames)
    {
        if (!paused)
            played = std::min<uint64_t>(written, played + frames);
    }
    void realTime(double seconds)
    {
        played = std::min<uint64_t>(written, static_cast<uint64_t>(seconds * kAudioRate));
    }

    static constexpr uint64_t kCapacity = kAudioRate;
    std::atomic<uint64_t> written{0}, played{0};
    std::atomic<double> energy{0};
    std::atomic<bool> paused{false};
};

struct Rgb
{
    int r, g, b;
};
Rgb centre(const Frame &frame)
{
    const uint8_t *p = frame.rgba.data() + (static_cast<size_t>(frame.height / 2) * frame.width + frame.width / 2) * 4;
    return {p[0], p[1], p[2]};
}
bool isRed(Rgb c)
{
    return c.r > 180 && c.g < 70 && c.b < 70;
}
bool isBlue(Rgb c)
{
    return c.b > 180 && c.r < 70 && c.g < 70;
}

void log(LogLevel level, const std::string &message)
{
    static const char *names[] = {"info", "warning", "error"};
    std::fprintf(stderr, "[video %s] %s\n", names[static_cast<int>(level)], message.c_str());
}

int clip(const char *path, int width, int height, double seconds, bool audio)
{
    auto *sinkPointer = audio ? new TestSink : nullptr;
    auto player = Player::open(openFile(path), path, std::unique_ptr<AudioSink>(sinkPointer));
    require(player != nullptr, "open failed");
    const StreamInfo &info = player->info();
    require(info.width == width && info.height == height && info.outputWidth == width && info.outputHeight == height,
            "picture size");
    require(audio == !info.audioCodec.empty(), "audio stream presence");
    require(info.videoDecoding == Decoding::Software, "host decodes in software");

    int shown = 0;
    bool firstRed = false, lastBlue = false, pausedChecked = false;
    const auto start = std::chrono::steady_clock::now();
    for (int step = 0; !player->finished(); ++step)
    {
        require(step < 20000, "playback did not finish");
        if (audio)
            sinkPointer->advance(kAudioRate / 100); // 10 ms per step on the audio clock
        std::this_thread::sleep_for(std::chrono::milliseconds(audio ? 2 : 1));
        bool changed = false;
        const Frame *frame = player->update(&changed);
        if (!frame || !changed)
            continue;
        require(frame->width == width && frame->height == height &&
                    frame->rgba.size() == static_cast<size_t>(width) * height * 4,
                "frame size");
        if (shown++ == 0)
            firstRed = isRed(centre(*frame));
        lastBlue = isBlue(centre(*frame));
        if (!pausedChecked && frame->pts > seconds / 4)
        {
            pausedChecked = true;
            player->setPaused(true);
            const double frozen = player->clock();
            std::this_thread::sleep_for(std::chrono::milliseconds(30));
            if (audio)
                sinkPointer->advance(kAudioRate);
            player->update(&changed);
            require(!changed && player->clock() == frozen, "pause freezes the clock");
            require(!audio || sinkPointer->paused, "pause reaches the audio output");
            player->setPaused(false);
        }
    }
    require(!player->failed(), "decode error");
    require(firstRed, "first frame is red");
    require(lastBlue, "last frame is blue");
    const int expected = static_cast<int>(std::lround(seconds * 10));
    require(shown >= expected * 8 / 10 && shown <= expected, "frames shown: " + std::to_string(shown));
    if (audio)
    {
        const double played = static_cast<double>(sinkPointer->written) / kAudioRate;
        require(std::abs(played - seconds) < 0.1, "audio length " + std::to_string(played));
        const double rms = std::sqrt(sinkPointer->energy / (sinkPointer->written * kAudioChannels));
        require(rms > 0.03 && rms < 0.5, "audio level " + std::to_string(rms));
    }
    else
    {
        const double elapsed = std::chrono::duration<double>(std::chrono::steady_clock::now() - start).count();
        require(elapsed > seconds * 0.9, "wall clock paced the video");
    }
    std::printf("PASS %s: %dx%d %s%s%s, %d/%d frames shown\n", path, width, height, info.videoCodec.c_str(),
                audio ? " + " : "", info.audioCodec.c_str(), shown, expected);
    return 0;
}

int smoke(const char *path, double seconds)
{
    auto *sinkPointer = new TestSink;
    auto player = Player::open(openFile(path), path, std::unique_ptr<AudioSink>(sinkPointer));
    require(player != nullptr, "open failed");
    if (player->info().audioCodec.empty())
        sinkPointer = nullptr; // the player released the unused sink
    const auto start = std::chrono::steady_clock::now();
    int shown = 0;
    double elapsed = 0, lastPts = 0;
    while (!player->finished() && (elapsed = std::chrono::duration<double>(std::chrono::steady_clock::now() - start).count()) < seconds)
    {
        if (sinkPointer)
            sinkPointer->realTime(elapsed);
        bool changed = false;
        const Frame *frame = player->update(&changed);
        if (frame && changed)
        {
            ++shown;
            lastPts = frame->pts;
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(4));
    }
    require(!player->failed(), "decode error");
    require(shown > 0, "no frame shown");
    const StreamInfo &info = player->info();
    std::printf("SMOKE %s: %dx%d %s -> %dx%d, audio %s %d Hz; %.1f s real time, %d frames shown (%.1f fps), "
                "last pts %.2f s, audio %.2f s written\n",
                path, info.width, info.height, info.videoCodec.c_str(), info.outputWidth, info.outputHeight,
                info.audioCodec.c_str(), info.audioRate, elapsed, shown, shown / elapsed, lastPts,
                sinkPointer ? double(sinkPointer->written) / kAudioRate : 0.0);
    return 0;
}
} // namespace

int main(int argc, char **argv)
try
{
    setLogSink(log);
    if (argc == 7 && !std::strcmp(argv[1], "clip"))
        return clip(argv[2], std::atoi(argv[3]), std::atoi(argv[4]), std::atof(argv[5]), std::atoi(argv[6]) != 0);
    if (argc == 4 && !std::strcmp(argv[1], "smoke"))
        return smoke(argv[2], std::atof(argv[3]));
    std::fprintf(stderr, "usage: video-check clip <file> <w> <h> <seconds> <audio> | smoke <file> <seconds>\n");
    return 2;
}
catch (const std::exception &error)
{
    std::fprintf(stderr, "FAIL %s: %s\n", argc > 2 ? argv[2] : "", error.what());
    return 1;
}
